/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-return */
import { describe, it, expect, beforeEach, vi } from "vitest";
import { of } from "rxjs";
import { ResponseTransformInterceptor } from "../../common/interceptors/response-transform.interceptor.js";

describe("ResponseTransformInterceptor (Unit)", () => {
  let interceptor: ResponseTransformInterceptor<any>;
  let mockReflector: any;
  let mockExecutionContext: any;
  let mockCallHandler: any;

  beforeEach(() => {
    mockReflector = {
      getAllAndOverride: vi.fn().mockReturnValue(false),
    };
    mockExecutionContext = {
      getHandler: vi.fn(),
      getClass: vi.fn(),
      switchToHttp: vi.fn().mockReturnValue({
        getResponse: vi.fn().mockReturnValue({ statusCode: 200 }),
        getRequest: vi.fn().mockReturnValue({ headers: {} }),
      }),
    };
    interceptor = new ResponseTransformInterceptor(mockReflector);
  });

  it("wrap response bình thường vào data payload", async () => {
    mockCallHandler = {
      handle: () => of({ id: "123", name: "Test" }),
    };

    const observable$ = interceptor.intercept(
      mockExecutionContext,
      mockCallHandler,
    );

    observable$.subscribe((res: any) => {
      expect(res.success).toBe(true);
      expect(res.code).toBe(200);
      expect(res.data).toEqual({ id: "123", name: "Test" });
      expect(res.meta.requestId).toBeDefined();
    });
  });

  it("trích xuất pagination khi response có _paginated flag", async () => {
    const paginatedData = {
      _paginated: true,
      items: [{ id: "1" }, { id: "2" }],
      pagination: {
        page: 1,
        pageSize: 10,
        totalItems: 2,
        totalPages: 1,
        hasNextPage: false,
        hasPreviousPage: false,
      },
    };

    mockCallHandler = {
      handle: () => of(paginatedData),
    };

    const observable$ = interceptor.intercept(
      mockExecutionContext,
      mockCallHandler,
    );

    observable$.subscribe((res: any) => {
      expect(res.success).toBe(true);
      expect(res.data).toEqual([{ id: "1" }, { id: "2" }]);
      expect(res.meta.pagination).toEqual(paginatedData.pagination);
    });
  });

  it("bỏ qua transform khi có @SkipResponseTransform decorator", async () => {
    mockReflector.getAllAndOverride.mockReturnValue(true);
    const rawData = { raw: "stream" };
    mockCallHandler = {
      handle: () => of(rawData),
    };

    const observable$ = interceptor.intercept(
      mockExecutionContext,
      mockCallHandler,
    );

    observable$.subscribe((res: any) => {
      expect(res).toEqual(rawData);
    });
  });
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-return */
import { describe, it, expect, beforeEach, vi } from "vitest";
import { NotFoundException, ConflictException } from "@nestjs/common";
import { RunService } from "../../modules/run/run.service.js";

describe("RunService (Unit)", () => {
  let runService: RunService;
  let mockPrisma: any;

  beforeEach(() => {
    mockPrisma = {
      run: {
        create: vi.fn(),
        findUnique: vi.fn(),
        findMany: vi.fn(),
        count: vi.fn(),
        updateMany: vi.fn(),
      },
      toolCall: {
        findMany: vi.fn(),
      },
      modelEvent: {
        findMany: vi.fn(),
      },
    };
    runService = new RunService(mockPrisma);
  });

  describe("createRun", () => {
    it("tạo run mới với config snapshot mặc định", async () => {
      const dto = {
        title: "Test Run",
        targetRepository: "owner/repo",
        findingId: "F-01",
      };

      mockPrisma.run.create.mockImplementation(async ({ data }: any) => ({
        id: "run-uuid-1",
        ...data,
      }));

      const result = await runService.createRun(dto);
      expect(result.id).toBe("run-uuid-1");
      expect(mockPrisma.run.create).toHaveBeenCalledOnce();
    });
  });

  describe("getRun", () => {
    it("trả về run nếu tìm thấy ID", async () => {
      const mockRun = { id: "run-1", title: "Run 1", status: "RUNNING" };
      mockPrisma.run.findUnique.mockResolvedValue(mockRun);

      const result = await runService.getRun("run-1");
      expect(result).toEqual(mockRun);
    });

    it("throw NotFoundException nếu không tìm thấy ID", async () => {
      mockPrisma.run.findUnique.mockResolvedValue(null);

      await expect(runService.getRun("non-existent")).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe("listRuns", () => {
    it("trả về danh sách phân trang đúng cấu trúc _paginated", async () => {
      mockPrisma.run.findMany.mockResolvedValue([{ id: "run-1" }]);
      mockPrisma.run.count.mockResolvedValue(1);

      const result = await runService.listRuns(1, 10);
      expect(result._paginated).toBe(true);
      expect(result.items).toHaveLength(1);
      expect(result.pagination.pageSize).toBe(10);
      expect(result.pagination.totalItems).toBe(1);
    });

    it("giới hạn (cap) pageSize tối đa 100 theo security protocol", async () => {
      mockPrisma.run.findMany.mockResolvedValue([]);
      mockPrisma.run.count.mockResolvedValue(0);

      const result = await runService.listRuns(1, 500);
      expect(result.pagination.pageSize).toBe(100);
    });
  });

  describe("cancelRun", () => {
    it("hủy run đang RUNNING thành công", async () => {
      mockPrisma.run.updateMany.mockResolvedValue({ count: 1 });
      mockPrisma.run.findUnique.mockResolvedValue({
        id: "run-1",
        status: "CANCELLED",
      });

      const result = await runService.cancelRun("run-1");
      expect(result?.status).toBe("CANCELLED");
      expect(mockPrisma.run.updateMany).toHaveBeenCalledWith({
        where: {
          id: "run-1",
          status: { notIn: ["COMPLETED", "FAILED", "CANCELLED"] },
        },
        data: {
          status: "CANCELLED",
          completedAt: expect.any(Date),
        },
      });
    });

    it("throw ConflictException nếu run đã ở trạng thái COMPLETED", async () => {
      mockPrisma.run.updateMany.mockResolvedValue({ count: 0 });
      mockPrisma.run.findUnique.mockResolvedValue({
        id: "run-1",
        status: "COMPLETED",
      });

      await expect(runService.cancelRun("run-1")).rejects.toThrow(
        ConflictException,
      );
    });
  });
});

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-return */
import { describe, it, expect, beforeEach, vi } from "vitest";
import { EventEmitter2 } from "@nestjs/event-emitter";
import { StreamService } from "../../modules/stream/stream.service.js";

describe("StreamService (Unit)", () => {
  let streamService: StreamService;
  let mockPrisma: any;
  let eventEmitter: EventEmitter2;

  beforeEach(() => {
    mockPrisma = {
      modelEvent: {
        findMany: vi.fn().mockResolvedValue([]),
      },
      toolCall: {
        findMany: vi.fn().mockResolvedValue([]),
      },
    };
    // C2 Fix: StreamService nhận EventEmitter2 làm dependency thứ 2
    eventEmitter = new EventEmitter2();
    streamService = new StreamService(mockPrisma, eventEmitter);
    // Simulate onModuleInit bridge setup
    streamService.onModuleInit();
  });

  it("phát live event khi không truyền fromStep", () => {
    const stream$ = streamService.getStreamForRun("run-1");
    const events: any[] = [];

    stream$.subscribe((e) => events.push(e));

    streamService.publishEvent({
      runId: "run-1",
      eventType: "step:thought",
      stepIndex: 1,
      payload: { thought: "Testing" },
    });

    expect(events.length).toBe(1);
    expect(events[0].type).toBe("step:thought");
  });

  it("không phát event của runId khác", () => {
    const stream$ = streamService.getStreamForRun("run-1");
    const events: any[] = [];

    stream$.subscribe((e) => events.push(e));

    // Publish event cho run-2 (không nên đến subscriber của run-1)
    streamService.publishEvent({
      runId: "run-2",
      eventType: "step:thought",
      stepIndex: 1,
      payload: { thought: "Should be filtered" },
    });

    expect(events.length).toBe(0);
  });
});

import {
  Catch,
  HttpException,
  HttpStatus,
  type ExceptionFilter,
  type ArgumentsHost,
  Logger,
} from "@nestjs/common";
import type { ApiErrorResponse } from "@audit-harness/contracts";

interface ExceptionResponseBody {
  message?: string;
  errorCode?: string;
  details?: Record<string, unknown>;
}

@Catch()
export class GlobalHttpExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger("HttpExceptionFilter");

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<{ status: (code: number) => { json: (body: ApiErrorResponse) => void } }>();
    const request = ctx.getRequest<{ method: string; url: string; headers: Record<string, string | undefined> }>();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    const exceptionResponse: ExceptionResponseBody | string =
      exception instanceof HttpException
        ? (exception.getResponse() as ExceptionResponseBody | string)
        : {
            message: "Internal server error",
            errorCode: "ERR_INTERNAL_SERVER",
          };

    // NI1 Fix: Log lỗi >= 500 để tành trạng production blindspot
    if (status >= 500) {
      this.logger.error(
        `[${request.method}] ${request.url} → ${status}`,
        exception instanceof Error ? exception.stack : String(exception),
      );
    } else if (status >= 400) {
      this.logger.warn(`[${request.method}] ${request.url} → ${status}`);
    }

    const respBody = typeof exceptionResponse === "string"
      ? { message: exceptionResponse, errorCode: undefined, details: undefined }
      : exceptionResponse;

    const errorPayload: ApiErrorResponse = {
      success: false,
      code: status,
      error: {
        code: respBody.errorCode ?? `ERR_HTTP_${status}`,
        message: respBody.message ?? "An error occurred",
        details: respBody.details,
      },
      meta: {
        requestId: request.headers["x-request-id"] || `req_${Date.now()}`,
        timestamp: new Date().toISOString(),
        path: request.url,
      },
    };

    response.status(status).json(errorPayload);
  }
}

import {
  Injectable,
  type NestInterceptor,
  type ExecutionContext,
  type CallHandler,
} from "@nestjs/common";
import { Reflector } from "@nestjs/core";
import { Observable } from "rxjs";
import { map } from "rxjs/operators";
import type {
  ApiSuccessResponse,
  PaginationMeta,
} from "@audit-harness/contracts";
import { SKIP_RESPONSE_TRANSFORM_KEY } from "../decorators/skip-response-transform.decorator.js";

@Injectable()
export class ResponseTransformInterceptor<T> implements NestInterceptor<
  T,
  ApiSuccessResponse<T> | T
> {
  constructor(private readonly reflector: Reflector) {}

  intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Observable<ApiSuccessResponse<T> | T> {
    const shouldSkip = this.reflector.getAllAndOverride<boolean>(
      SKIP_RESPONSE_TRANSFORM_KEY,
      [context.getHandler(), context.getClass()],
    );

    if (shouldSkip) {
      return next.handle();
    }

    const ctx = context.switchToHttp();
    const response = ctx.getResponse();
    const request = ctx.getRequest();

    return next.handle().pipe(
      map((result) => {
        /**
         * NC3 Fix: Bỏ heuristic result.data detection — nguy hiểm vì bất kỳ
         * DTO nào có field .data sẽ bị unwrap nhầm.
         *
         * Convention mới: Controller trả về object có shape { _paginated: true, items, pagination }
         * để interceptor nhận biết pagination một cách explicit thay vì heuristic.
         *
         * Mặc định: wrap toàn bộ result vào data.
         */
        let data: T = result;
        let pagination: PaginationMeta | undefined;
        const message =
          result && typeof result === "object" && result.message
            ? result.message
            : "Operation successful";

        // Chỉ extract pagination khi controller dùng convention _paginated flag
        if (
          result &&
          typeof result === "object" &&
          result._paginated === true
        ) {
          data = result.items as T;
          pagination = result.pagination as PaginationMeta;
        }

        const responsePayload: ApiSuccessResponse<T> = {
          success: true,
          code: response.statusCode,
          message,
          data,
          meta: {
            requestId:
              (request.headers["x-request-id"] as string) ||
              `req_${Date.now()}`,
            timestamp: new Date().toISOString(),
            ...(pagination ? { pagination } : {}),
          },
        };

        return responsePayload;
      }),
    );
  }
}

import {
  type PipeTransform,
  type ArgumentMetadata,
  BadRequestException,
} from "@nestjs/common";
import { type ZodSchema, ZodError } from "zod";

export class ZodValidationPipe implements PipeTransform {
  constructor(private schema: ZodSchema) {}

  transform(value: unknown) {
    try {
      return this.schema.parse(value);
    } catch (error) {
      if (error instanceof ZodError) {
        const details = error.errors.map((e) => ({
          field: e.path.join("."),
          issue: e.message,
        }));
        throw new BadRequestException({
          errorCode: "ERR_VALIDATION_FAILED",
          message: "Invalid request body parameters",
          details,
        });
      }
      throw new BadRequestException("Validation failed");
    }
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from "@nestjs/common";
import { readFile } from "fs/promises";
import { join } from "path";
import { z } from "zod";

const DemoEventSchema = z.object({
  type: z.enum([
    "step:thought",
    "step:tool_call",
    "run:verdict",
    "run:completed",
    "run:status_changed",
    "heartbeat",
  ]),
  payload: z.record(z.unknown()),
  delayMs: z.number().optional(),
});

const DemoFixtureSchema = z.object({
  events: z.array(DemoEventSchema),
});

export type DemoEvent = z.infer<typeof DemoEventSchema>;
export type DemoFixture = z.infer<typeof DemoFixtureSchema>;

@Injectable()
export class DemoService {
  async loadDemoFixture(runId: string): Promise<DemoFixture> {
    const fixturePath = join(process.cwd(), "demo-fixtures", `${runId}.json`);
    try {
      const raw = await readFile(fixturePath, "utf-8");
      const parsed = JSON.parse(raw);
      return DemoFixtureSchema.parse(parsed);
    } catch (err) {
      if (err instanceof z.ZodError) {
        throw new BadRequestException(
          `Demo fixture '${runId}' có format không hợp lệ: ${err.message}`,
        );
      }
      throw new NotFoundException(`Demo fixture '${runId}' không tồn tại`);
    }
  }
}

import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  Query,
  Res,
  UsePipes,
  Header,
  Headers,
  BadRequestException,
} from "@nestjs/common";
import type { Response } from "express";
import { CreateRunSchema, type CreateRunDto } from "@audit-harness/contracts";
import { RunService } from "./run.service.js";
import { ZodValidationPipe } from "../../common/pipes/zod-validation.pipe.js";
import { SkipResponseTransform } from "../../common/decorators/skip-response-transform.decorator.js";

@Controller("runs")
export class RunController {
  constructor(private readonly runService: RunService) {}

  @Post()
  @UsePipes(new ZodValidationPipe(CreateRunSchema))
  async createRun(@Body() dto: CreateRunDto) {
    return this.runService.createRun(dto);
  }

  @Get()
  async listRuns(
    @Query("page") page?: string,
    @Query("pageSize") pageSize?: string,
    @Query("status") status?: string,
  ) {
    const p = page ? parseInt(page, 10) : 1;
    const ps = pageSize ? parseInt(pageSize, 10) : 10;
    return this.runService.listRuns(p, ps, status);
  }

  @Get(":id")
  async getRun(@Param("id") id: string) {
    return this.runService.getRun(id);
  }

  @Get(":id/tool-calls")
  async getToolCalls(
    @Param("id") id: string,
    @Query("fromStep") fromStep?: string,
    @Query("limit") limit?: string,
  ) {
    const fs = fromStep ? parseInt(fromStep, 10) : 0;
    const l = limit ? parseInt(limit, 10) : 50;
    return this.runService.getToolCalls(id, fs, l);
  }

  @Get(":id/model-events")
  async getModelEvents(
    @Param("id") id: string,
    @Query("fromStep") fromStep?: string,
    @Query("limit") limit?: string,
  ) {
    const fs = fromStep ? parseInt(fromStep, 10) : 0;
    const l = limit ? parseInt(limit, 10) : 50;
    return this.runService.getModelEvents(id, fs, l);
  }

  @Post(":id/cancel")
  async cancelRun(
    @Param("id") id: string,
    @Headers("x-request-id") requestId?: string,
  ) {
    // W5 Fix: x-request-id bắt buộc cho idempotency trace theo spec
    if (!requestId || requestId.trim() === "") {
      throw new BadRequestException({
        errorCode: "ERR_MISSING_REQUEST_ID",
        message: "Header 'x-request-id' là bắt buộc cho endpoint cancel.",
      });
    }
    return this.runService.cancelRun(id);
  }

  @Get(":id/export")
  @SkipResponseTransform()
  @Header("Content-Type", "application/json")
  async exportRunData(@Param("id") id: string, @Res() res: Response) {
    const EXPORT_LIMIT = 200;
    const run = await this.runService.getRun(id);
    const toolCalls = await this.runService.getToolCalls(id, 0, EXPORT_LIMIT);
    const modelEvents = await this.runService.getModelEvents(
      id,
      0,
      EXPORT_LIMIT,
    );

    // W6 Fix: Cảnh báo rõ ràng khi data bị truncate thay vì âm thầm mất dữ liệu
    const isTruncated =
      toolCalls.length === EXPORT_LIMIT || modelEvents.length === EXPORT_LIMIT;

    const payload = {
      run,
      toolCalls,
      modelEvents,
      exportedAt: new Date().toISOString(),
      meta: {
        exportLimit: EXPORT_LIMIT,
        isTruncated,
        truncationWarning: isTruncated
          ? `Dữ liệu bị giới hạn ở ${EXPORT_LIMIT} records. Sử dụng API pagination để lấy toàn bộ.`
          : null,
      },
    };

    res.setHeader(
      "Content-Disposition",
      `attachment; filename="run-${id}-export.json"`,
    );
    res.json(payload);
  }
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
} from "@nestjs/common";
import { createHash } from "crypto";
import type { CreateRunDto } from "@audit-harness/contracts";
import { PrismaService } from "../prisma/prisma.service.js";

@Injectable()
export class RunService {
  constructor(private readonly prisma: PrismaService) {}

  private buildConfigSnapshot(dto: CreateRunDto) {
    const config = (dto.config as { modelProvider?: string; modelName?: string; temperature?: number; maxSteps?: number; enableMemory?: boolean; enableCompaction?: boolean; enableVerification?: boolean }) ?? {};
    const userProvided = {
      modelProvider: config.modelProvider ?? "fake",
      modelName: config.modelName ?? "claude-3-5-sonnet",
      temperature: config.temperature ?? 0.0,
      maxSteps: config.maxSteps ?? 50,
      enableMemory: config.enableMemory ?? true,
      enableCompaction: config.enableCompaction ?? true,
      enableVerification: config.enableVerification ?? true,
    };

    const TOKEN_PER_STEP_ESTIMATE = 3000;
    const systemGenerated = {
      promptVersion: process.env["PROMPT_VERSION"] ?? "v1.0.0",
      tokenBudget: Math.min(
        userProvided.maxSteps * TOKEN_PER_STEP_ESTIMATE,
        200000,
      ),
      configHash: createHash("sha256")
        .update(JSON.stringify(userProvided))
        .digest("hex")
        .slice(0, 32),
    };

    return { ...userProvided, ...systemGenerated };
  }

  async createRun(dto: CreateRunDto) {
    const snapshotData = this.buildConfigSnapshot(dto);
    const run = await this.prisma.run.create({
      data: {
        title: dto.title,
        targetRepository: dto.targetRepository,
        findingId: dto.findingId,
        status: "PENDING",
        configSnapshot: {
          create: snapshotData,
        },
      },
      include: {
        configSnapshot: true,
      },
    });

    return run;
  }

  async getRun(id: string) {
    const run = await this.prisma.run.findUnique({
      where: { id },
      include: {
        configSnapshot: true,
        verdict: true,
      },
    });
    if (!run) {
      throw new NotFoundException(`Run with ID '${id}' was not found`);
    }
    return run;
  }

  async listRuns(page = 1, pageSize = 10, status?: string) {
    // NW1 Fix: Cap pageSize theo spec 03-security-protocol.md (limit ≤ 100)
    const safePageSize = Math.min(pageSize, 100);
    const skip = (page - 1) * safePageSize;
    const where = status ? { status: status as import("@prisma/client").RunStatus } : {};

    const [items, totalItems] = await Promise.all([
      this.prisma.run.findMany({
        where,
        skip,
        take: safePageSize,
        orderBy: { createdAt: "desc" },
      }),
      this.prisma.run.count({ where }),
    ]);

    const totalPages = Math.ceil(totalItems / safePageSize);

    // NC3 Fix: Dùng _paginated flag convention thay vì { data, pagination }
    // để ResponseTransformInterceptor nhận biết explicit (không heuristic)
    return {
      _paginated: true as const,
      items,
      pagination: {
        page,
        pageSize: safePageSize,
        totalItems,
        totalPages,
        hasNextPage: page < totalPages,
        hasPreviousPage: page > 1,
      },
    };
  }

  async getToolCalls(runId: string, fromStep = 0, limit = 50) {
    await this.getRun(runId);
    return this.prisma.toolCall.findMany({
      where: { runId, stepIndex: { gte: fromStep } },
      take: Math.min(limit, 200),
      orderBy: { stepIndex: "asc" },
    });
  }

  async getModelEvents(runId: string, fromStep = 0, limit = 50) {
    await this.getRun(runId);
    return this.prisma.modelEvent.findMany({
      where: { runId, stepIndex: { gte: fromStep } },
      take: Math.min(limit, 200),
      orderBy: { stepIndex: "asc" },
    });
  }

  async cancelRun(runId: string) {
    // NW6 Fix: Atomic updateMany với điều kiện where — tránh TOCTOU race
    // Thay vì read-check-write (3 bước), dùng 1 operation nguyên tử:
    // Chỉ update nếu run hiện tại KHÔNG ở terminal state
    const result = await this.prisma.run.updateMany({
      where: {
        id: runId,
        status: { notIn: ["COMPLETED", "FAILED", "CANCELLED"] },
      },
      data: {
        status: "CANCELLED",
        completedAt: new Date(),
      },
    });

    if (result.count === 0) {
      // Run không tồn tại hoặc đã ở terminal state
      const run = await this.prisma.run.findUnique({ where: { id: runId } });
      if (!run) {
        throw new NotFoundException(`Run with ID '${runId}' was not found`);
      }
      throw new ConflictException({
        errorCode: "ERR_RUN_ALREADY_TERMINAL",
        message: `Run '${runId}' is already in a terminal state: ${run.status}`,
      });
    }

    return this.prisma.run.findUnique({
      where: { id: runId },
      include: { configSnapshot: true, verdict: true },
    });
  }
}

import {
  Injectable,
  type MessageEvent,
  type OnModuleInit,
} from "@nestjs/common";
import { EventEmitter2 } from "@nestjs/event-emitter";
import { Subject, Observable, filter, map, merge, from } from "rxjs";
import { mergeMap, distinct } from "rxjs/operators";
import { PrismaService } from "../prisma/prisma.service.js";

export interface HarnessStreamEvent {
  runId: string;
  eventType: string;
  stepIndex?: number;
  payload: Record<string, unknown>;
}

/**
 * Tên event chuẩn cho EventEmitter2 internal bus.
 * Worker (cùng process) emit event này → StreamService forward qua SSE.
 *
 * @note Kiến trúc extensible: khi Worker tách thành process riêng,
 * thay LocalEventBusAdapter bằng RedisEventBusAdapter mà không cần
 * sửa StreamService hay Controller.
 */
export const HARNESS_STREAM_EVENT = "harness.stream.event";

@Injectable()
export class StreamService implements OnModuleInit {
  /**
   * Internal Subject — nhận event từ EventEmitter2 (local bus)
   * và broadcast đến tất cả SSE subscriber của cùng runId.
   */
  private readonly eventSubject$ = new Subject<HarnessStreamEvent>();

  constructor(
    private readonly prisma: PrismaService,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  /**
   * Bridge: EventEmitter2 → RxJS Subject.
   * Đảm bảo mọi service trong cùng process đều có thể publish event
   * mà không cần inject StreamService trực tiếp (tránh circular dependency).
   */
  onModuleInit() {
    this.eventEmitter.on(HARNESS_STREAM_EVENT, (event: HarnessStreamEvent) => {
      this.eventSubject$.next(event);
    });
  }

  /**
   * Publish event lên local bus. Dùng cho Demo mode và Worker (same-process).
   * EventEmitter2 listener ở onModuleInit() sẽ forward vào Subject.
   */
  public publishEvent(event: HarnessStreamEvent): void {
    this.eventEmitter.emit(HARNESS_STREAM_EVENT, event);
  }

  public getStreamForRun(
    runId: string,
    fromStep?: number,
  ): Observable<MessageEvent> {

    const liveStream$ = this.eventSubject$.asObservable().pipe(
      filter((event) => event.runId === runId),
      filter(
        (event) => fromStep === undefined || (event.stepIndex ?? -1) > fromStep,
      ),
      map((event: HarnessStreamEvent): MessageEvent => ({
        // NC2 Fix: composite id = eventType:stepIndex cho live events
        id: `${event.eventType}:${event.stepIndex ?? Date.now()}`,
        type: event.eventType,
        data: JSON.stringify(event.payload),
      })),
    );

    if (fromStep === undefined || fromStep < 0) {
      return liveStream$;
    }

    const historicalReplay$ = from(
      this.replayHistoricalEvents(runId, fromStep),
    ).pipe(mergeMap((events) => from(events)));

    return merge(historicalReplay$, liveStream$).pipe(
      // NC2 Fix: distinct theo composite key type:stepIndex
      // Tránh drop event khi cùng 1 step có cả ModelEvent (THOUGHT) lẫn ToolCall
      distinct((event: MessageEvent) => `${event.type}:${event.id}`),
    );
  }

  private async replayHistoricalEvents(
    runId: string,
    fromStep: number,
  ): Promise<MessageEvent[]> {
    const [modelEvents, toolCalls] = await Promise.all([
      this.prisma.modelEvent.findMany({
        where: { runId, stepIndex: { gt: fromStep } },
        orderBy: { stepIndex: "asc" },
      }),
      this.prisma.toolCall.findMany({
        where: { runId, stepIndex: { gt: fromStep } },
        orderBy: { stepIndex: "asc" },
      }),
    ]);

    return [
      ...modelEvents.map((e: import("@prisma/client").ModelEvent) => ({
        // NC2 Fix: composite id = type:stepIndex để không conflict với ToolCall cùng step
        id: `${this.mapEventType(e.eventType)}:${e.stepIndex}`,
        type: this.mapEventType(e.eventType),
        data: JSON.stringify({
          runId,
          stepIndex: e.stepIndex,
          content: e.content,
        }),
      })),
      ...toolCalls.map((tc: import("@prisma/client").ToolCall) => ({
        // NC2 Fix: composite id = step:tool_call:stepIndex
        id: `step:tool_call:${tc.stepIndex}`,
        type: "step:tool_call",
        data: JSON.stringify({
          runId,
          stepIndex: tc.stepIndex,
          toolName: tc.toolName,
          arguments: JSON.parse(tc.argumentsJson as string),
          result: tc.resultJson,
          isError: tc.isError,
          durationMs: tc.durationMs,
          tokensUsed: tc.tokensUsed,
        }),
      })),
    ].sort((a, b) => {
      // Sort by stepIndex (parse từ phần cuối composite id)
      const stepA = parseInt(a.id.split(":").pop()!, 10);
      const stepB = parseInt(b.id.split(":").pop()!, 10);
      return stepA - stepB;
    });
  }

  private mapEventType(dbEventType: string): string {
    const mapping: Record<string, string> = {
      THOUGHT: "step:thought",
      TOOL_REQUEST: "step:tool_call",
      SYSTEM_PROMPT: "run:status_changed",
      ERROR: "run:status_changed",
    };
    return mapping[dbEventType] ?? "run:status_changed";
  }
}

