interface TraceHeaderProps {
  run: Run | null;
}

export const TraceHeader: React.FC<TraceHeaderProps> = ({ run }) => {
  const { sseStatus, setRun } = useRunStore();
  const client = useAuditHarnessClient();

  const getSseBadge = (status: SseStatus) => {
    switch (status) {
      case "connected":
        return (
          <span
            style={{
              color: "#10b981",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            🟢 Connected
          </span>
        );
      case "reconnecting":
        return (
          <span
            style={{
              color: "#f59e0b",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            🟡 Reconnecting...
          </span>
        );
      case "connecting":
        return (
          <span
            style={{
              color: "#06b6d4",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            ⏳ Connecting...
          </span>
        );
      case "offline":
      default:
        return (
          <span
            style={{
              color: "#6b7280",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            ⚪ Offline
          </span>
        );
    }
  };

  const handleAbortRun = async () => {
    if (!run) return;
    const confirmed = window.confirm(
      "Abort Audit Run?\nHành động này sẽ dừng Agent Loop ngay lập tức. Dữ liệu đã ghi được giữ nguyên.",
    );
    if (!confirmed) return;

    try {
      const updated = await client.cancelRun(run.id);
      setRun(updated);
    } catch (err: unknown) {
      alert("Không thể hủy run: " + (err instanceof Error ? err.message : String(err)));
    }
  };

  return (
    <header
      className="glass-panel"
      style={{
        padding: "16px 24px",
        borderRadius: "12px",
        marginBottom: "20px",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <div>
          <h1
            style={{ fontSize: "1.25rem", fontWeight: 700, color: "#f9fafb" }}
          >
            {run?.title || "Audit Run Trace View"}
          </h1>
          <p
            style={{ fontSize: "0.875rem", color: "#9ca3af", marginTop: "4px" }}
          >
            Repository:{" "}
            <code style={{ color: "#06b6d4" }}>
              {run?.targetRepository || "N/A"}
            </code>{" "}
            | Finding ID:{" "}
            <code style={{ color: "#3b82f6" }}>{run?.findingId || "N/A"}</code>
          </p>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
          <div
            style={{
              padding: "6px 12px",
              background: "#111827",
              borderRadius: "8px",
              fontSize: "0.875rem",
            }}
          >
            {getSseBadge(sseStatus)}
          </div>

          {run?.status === "RUNNING" && (
            <button
              onClick={() => { void handleAbortRun(); }}
              style={{
                background: "#f43f5e",
                color: "#ffffff",
                padding: "8px 16px",
                borderRadius: "8px",
                fontWeight: 600,
                fontSize: "0.875rem",
              }}
            >
              Abort Run
            </button>
          )}

          <div
            style={{
              padding: "6px 12px",
              background:
                run?.status === "RUNNING"
                  ? "rgba(59, 130, 246, 0.2)"
                  : "rgba(16, 185, 129, 0.2)",
              color: run?.status === "RUNNING" ? "#3b82f6" : "#10b981",
              borderRadius: "8px",
              fontWeight: 600,
              fontSize: "0.875rem",
            }}
          >
            {run?.status || "IDLE"}
          </div>
        </div>
      </div>
    </header>
  );
};

import React, { useEffect, useRef, useState } from "react";
import { useAuditHarnessClient } from "../../hooks/useAuditHarnessClient.js";
import { useRunStore } from "../../stores/run.store.js";
import { TraceHeader } from "./TraceHeader.js";
import { VerdictBanner } from "./VerdictBanner.js";
import { ToolCallCard } from "./ToolCallCard.js";
import { RefreshCw, AlertCircle } from "lucide-react";

interface TraceViewProps {
  runId: string;
}

export const TraceView: React.FC<TraceViewProps> = ({ runId }) => {
  const client = useAuditHarnessClient();
  const {
    currentRun,
    toolCalls,
    setRun,
    setRunStatus,
    appendToolCall,
    appendThought,
    setSseStatus,
    reset,
  } = useRunStore();

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const unsubscribeRef = useRef<(() => void) | null>(null);

  const fetchAndSubscribe = async (isCancelled: () => boolean) => {
    setIsLoading(true);
    setError(null);
    reset();

    // Hủy subscription trước đó nếu có
    if (unsubscribeRef.current) {
      unsubscribeRef.current();
      unsubscribeRef.current = null;
    }

    try {
      // Step 1: REST GET /api/v1/runs/:id (Hydrate run metadata)
      const runData = await client.getRun(runId);
      if (isCancelled()) return;
      setRun(runData);

      // Step 2: REST GET /api/v1/runs/:id/tool-calls (Hydrate full tool call history)
      const historicalToolCalls = await client.getToolCalls(runId, {
        fromStep: 0,
        limit: 500,
      });
      if (isCancelled()) return;
      historicalToolCalls.forEach(appendToolCall);

      setIsLoading(false);

      // Step 3: Connect SSE Stream nếu RUNNING
      if (runData.status === "RUNNING") {
        setSseStatus("connecting");

        const maxStepIndex =
          historicalToolCalls.length > 0
            ? Math.max(...historicalToolCalls.map((tc) => tc.stepIndex))
            : 0;

        const unsubscribe = client.subscribeRunStream(
          runId,
          {
            onopen: () => {
              if (!isCancelled()) setSseStatus("connected");
            },
            onThought: (e) => {
              if (!isCancelled()) appendThought(e);
            },
            onToolCall: (e) => {
              if (!isCancelled()) appendToolCall(e);
            },
            onStatusChanged: (e) => {
              if (!isCancelled()) setRunStatus(e.status);
            },
            onVerdict: () => {
              if (!isCancelled()) {
                client
                  .getRun(runId)
                  .then((updated) => {
                    if (!isCancelled()) setRun(updated);
                  })
                  .catch(() => {});
              }
            },
            onCompleted: () => {
              if (!isCancelled()) {
                setSseStatus("offline");
                client
                  .getRun(runId)
                  .then((updated) => {
                    if (!isCancelled()) setRun(updated);
                  })
                  .catch(() => {});
              }
            },
            onError: () => {
              if (!isCancelled()) setSseStatus("reconnecting");
            },
          },
          { fromStep: maxStepIndex },
        );

        if (!isCancelled()) {
          unsubscribeRef.current = unsubscribe;
        } else {
          unsubscribe();
        }
      } else {
        setSseStatus("offline");
      }
    } catch (err: unknown) {
      if (isCancelled()) return;
      console.error("Initialization error in TraceView:", err);
      setError(err instanceof Error ? err.message : String(err));
      setSseStatus("offline");
      setIsLoading(false);
    }
  };

  useEffect(() => {
    let cancelled = false;
    const isCancelled = () => cancelled;

    void fetchAndSubscribe(isCancelled);

    return () => {
      cancelled = true;
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
        unsubscribeRef.current = null;
      }
    };
  }, [runId]);

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "24px" }}>
      <TraceHeader run={currentRun} />

      {currentRun?.verdict && <VerdictBanner verdict={currentRun.verdict} />}

      {/* State: Error alert */}
      {error && (
        <div
          className="glass-panel"
          style={{
            padding: "20px 24px",
            borderRadius: "12px",
            background: "rgba(244, 63, 94, 0.1)",
            border: "1px solid rgba(244, 63, 94, 0.3)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginTop: "20px",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <AlertCircle size={20} color="#f43f5e" />
            <span style={{ color: "#fca5a5", fontSize: "0.9rem" }}>
              {error}
            </span>
          </div>
          <button
            onClick={() => { void fetchAndSubscribe(() => false); }}
            style={{
              padding: "6px 14px",
              background: "#f43f5e",
              color: "#fff",
              borderRadius: "6px",
              fontWeight: 600,
              fontSize: "0.85rem",
              display: "flex",
              alignItems: "center",
              gap: "6px",
            }}
          >
            <RefreshCw size={14} /> Thử lại
          </button>
        </div>
      )}

      <div style={{ marginTop: "20px" }}>
        <h3
          style={{
            fontSize: "1rem",
            fontWeight: 600,
            color: "#9ca3af",
            marginBottom: "16px",
          }}
        >
          Agent Execution Trajectory ({toolCalls.length} Tool Calls)
        </h3>

        {/* State: Loading Skeleton */}
        {isLoading ? (
          <div
            className="glass-panel"
            style={{
              padding: "40px",
              textAlign: "center",
              color: "#06b6d4",
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "10px",
            }}
          >
            <RefreshCw className="animate-spin" size={20} />
            <span>Đang tải dữ liệu Audit Run...</span>
          </div>
        ) : toolCalls.length === 0 ? (
          <div
            className="glass-panel"
            style={{
              padding: "40px",
              textAlign: "center",
              color: "#6b7280",
              borderRadius: "12px",
            }}
          >
            No execution steps recorded yet.
          </div>
        ) : (
          <div>
            {toolCalls.map((tc) => (
              <ToolCallCard key={tc.id} toolCall={tc} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React from "react";
import type { Verdict } from "@audit-harness/contracts";

interface VerdictBannerProps {
  verdict: Verdict | null | undefined;
}

export const VerdictBanner: React.FC<VerdictBannerProps> = ({ verdict }) => {
  if (!verdict) return null;

  const isSuccess = verdict.status === "VALID";

  return (
    <div
      style={{
        background: isSuccess
          ? "rgba(16, 185, 129, 0.1)"
          : "rgba(244, 63, 94, 0.1)",
        border: `1px solid ${isSuccess ? "#10b981" : "#f43f5e"}`,
        borderRadius: "12px",
        padding: "20px",
        marginBottom: "24px",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "12px",
        }}
      >
        <h3
          style={{
            fontSize: "1.1rem",
            fontWeight: 700,
            color: isSuccess ? "#10b981" : "#f43f5e",
          }}
        >
          Audit Verdict: {verdict.status} ({verdict.severity})
        </h3>
        <span style={{ fontSize: "0.875rem", color: "#9ca3af" }}>
          Confidence: {Math.round(verdict.confidenceScore * 100)}%
        </span>
      </div>
      <p style={{ color: "#d1d5db", fontSize: "0.95rem", lineHeight: "1.5" }}>
        {verdict.explanation}
      </p>
      {verdict.pocSourceCode && (
        <div style={{ marginTop: "16px" }}>
          <h4
            style={{
              fontSize: "0.875rem",
              color: "#9ca3af",
              marginBottom: "8px",
            }}
          >
            Verification PoC Test:
          </h4>
          <pre
            style={{
              background: "#111827",
              padding: "12px",
              borderRadius: "8px",
              overflowX: "auto",
              fontSize: "0.85rem",
              color: "#38bdf8",
            }}
          >
            {verdict.pocSourceCode}
          </pre>
        </div>
      )}
    </div>
  );
};

import { createContext, useContext, useMemo } from "react";
import { AuditHarnessClient } from "@audit-harness/sdk";

/**
 * NI3 Fix: Chuyển từ per-mount instance sang React Context singleton.
 * Tránh tạo nhiều client instance khi component mount/unmount.
 */
const AuditHarnessClientContext = createContext<AuditHarnessClient | null>(
  null,
);

export function AuditHarnessClientProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const client = useMemo(
    () => new AuditHarnessClient({ baseUrl: window.location.origin }),
    [],
  );

  return (
    <AuditHarnessClientContext.Provider value={client}>
      {children}
    </AuditHarnessClientContext.Provider>
  );
}

export function useAuditHarnessClient(): AuditHarnessClient {
  const client = useContext(AuditHarnessClientContext);
  if (!client) {
    throw new Error(
      "useAuditHarnessClient phải được dùng bên trong <AuditHarnessClientProvider>",
    );
  }
  return client;
}

import { create } from "zustand";
import type { Run, ToolCall, ModelEvent } from "@audit-harness/contracts";
import type { ThoughtEvent, ToolCallEvent } from "@audit-harness/sdk";

export type SseStatus = "connecting" | "connected" | "reconnecting" | "offline";

interface RunState {
  currentRun: Run | null;
  toolCalls: ToolCall[];
  modelEvents: ModelEvent[];
  sseStatus: SseStatus;

  setRun: (run: Run | null) => void;
  /** NW3 Fix: Patch chỉ 1 field status mà không cần có snapshot của toàn bộ run */
  setRunStatus: (status: string) => void;
  setSseStatus: (status: SseStatus) => void;
  appendToolCall: (tc: ToolCall | ToolCallEvent) => void;
  appendThought: (thought: ThoughtEvent) => void;
  reset: () => void;
}

export const useRunStore = create<RunState>((set) => ({
  currentRun: null,
  toolCalls: [],
  modelEvents: [],
  sseStatus: "offline",

  setRun: (run) => set({ currentRun: run }),
  // NW3 Fix: Dùng functional updater — không phụ thuộc snapshot của run tại thời điểm subscribe
  setRunStatus: (status) =>
    set((state) => ({
      currentRun: state.currentRun
        ? { ...state.currentRun, status: status as Run["status"] }
        : null,
    })),
  setSseStatus: (sseStatus) => set({ sseStatus }),

  appendToolCall: (tc) =>
    set((state) => {
      const formatted: ToolCall = {
        id: (tc as ToolCall).id || `tc_${tc.stepIndex}_${Date.now()}`,
        runId: tc.runId,
        stepIndex: tc.stepIndex,
        toolName: tc.toolName,
        argumentsJson:
          (tc as ToolCall).argumentsJson ||
          JSON.stringify((tc as ToolCallEvent).arguments || {}),
        resultJson:
          (tc as ToolCall).resultJson || (tc as ToolCallEvent).result || "",
        isError: tc.isError,
        durationMs: tc.durationMs,
        tokensUsed: tc.tokensUsed,
        timestamp: (tc as ToolCall).timestamp || new Date().toISOString(),
      };

      // W4 Fix: De-duplicate theo composite key runId+stepIndex+toolName
      // Tránh trường hợp REST prefetch trả ToolCall (có .id thật) và SSE trả
      // ToolCallEvent (không có .id) sinh key khác nhau cho cùng 1 record.
      const compositeKey = `${formatted.runId}:${formatted.stepIndex}:${formatted.toolName}`;
      const exists = state.toolCalls.some(
        (existing) =>
          `${existing.runId}:${existing.stepIndex}:${existing.toolName}` ===
          compositeKey,
      );
      if (exists) return state;

      return { toolCalls: [...state.toolCalls, formatted] };
    }),

  appendThought: (thought) =>
    set((state) => {
      // NW2 Fix: De-duplicate theo runId+stepIndex (giống appendToolCall)
      const exists = state.modelEvents.some(
        (e) => e.runId === thought.runId && e.stepIndex === thought.stepIndex,
      );
      if (exists) return state;

      const formatted: ModelEvent = {
        id: `me_${thought.stepIndex}_${Date.now()}`,
        runId: thought.runId,
        stepIndex: thought.stepIndex,
        eventType: "THOUGHT",
        content: thought.thought,
        tokensUsed: thought.tokensUsed,
        timestamp: new Date().toISOString(),
      };
      return { modelEvents: [...state.modelEvents, formatted] };
    }),

  reset: () =>
    set({
      currentRun: null,
      toolCalls: [],
      modelEvents: [],
      sseStatus: "offline",
    }),
}));

import { describe, it, expect, vi, beforeEach } from "vitest";
import { AuditHarnessClient } from "../client.js";

describe("AuditHarnessClient", () => {
  let client: AuditHarnessClient;

  beforeEach(() => {
    client = new AuditHarnessClient({
      baseUrl: "http://localhost:3000",
    });
    vi.restoreAllMocks();
  });

  it("gửi request POST /api/v1/runs thành công", async () => {
    const mockRun = {
      id: "run-123",
      title: "Reentrancy Verification",
      targetRepository: "code4rena/vault",
      findingId: "H-01",
      status: "PENDING",
      createdAt: new Date().toISOString(),
    };

    vi.spyOn(global, "fetch").mockResolvedValueOnce({
      ok: true,
      json: async () => ({
        success: true,
        code: 201,
        message: "Run initiated",
        data: mockRun,
        meta: { requestId: "req_1", timestamp: new Date().toISOString() },
      }),
    } as unknown as Response);

    const result = await client.createRun({
      title: "Reentrancy Verification",
      targetRepository: "code4rena/vault",
      findingId: "H-01",
    });

    expect(result).toEqual(mockRun);
    expect(global.fetch).toHaveBeenCalledWith(
      "http://localhost:3000/api/v1/runs",
      expect.objectContaining({
        method: "POST",
      }),
    );
  });

  it("gửi request POST /api/v1/runs/:id/cancel để hủy run", async () => {
    const mockCancelled = {
      id: "run-123",
      status: "CANCELLED",
    };

    vi.spyOn(global, "fetch").mockResolvedValueOnce({
      ok: true,
      json: async () => ({
        success: true,
        code: 200,
        message: "Run cancelled",
        data: mockCancelled,
        meta: { requestId: "req_2", timestamp: new Date().toISOString() },
      }),
    } as unknown as Response);

    const result = await client.cancelRun("run-123");

    expect(result).toEqual(mockCancelled);
    expect(global.fetch).toHaveBeenCalledWith(
      "http://localhost:3000/api/v1/runs/run-123/cancel",
      expect.objectContaining({
        method: "POST",
      }),
    );
  });
});

import { fetchEventSource } from "@microsoft/fetch-event-source";
import type {
  Run,
  CreateRunDto,
  ToolCall,
  ModelEvent,
  ApiSuccessResponse,
  ApiErrorResponse,
  PaginationMeta,
} from "@audit-harness/contracts";
import type {
  AuditHarnessClientOptions,
  StreamConnectionOptions,
  RunStreamListener,
  ThoughtEvent,
  ToolCallEvent,
  StatusChangedEvent,
  VerdictEvent,
  CompletedEvent,
  PaginatedResult,
} from "./types.js";
import {
  HarnessSDKError,
  RunNotFoundError,
  NetworkDisconnectedError,
} from "./errors.js";

export class AuditHarnessClient {
  private readonly baseUrl: string;
  private readonly defaultHeaders: Record<string, string>;

  constructor(options: AuditHarnessClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/$/, "");
    this.defaultHeaders = {
      "Content-Type": "application/json",
      ...(options.apiKey && { Authorization: `Bearer ${options.apiKey}` }),
    };
  }

  private async request<T>(path: string, init?: RequestInit): Promise<T> {
    const url = `${this.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
    let res: Response;
    try {
      res = await fetch(url, {
        ...init,
        headers: {
          ...this.defaultHeaders,
          ...init?.headers,
        },
      });
    } catch (err) {
      throw new NetworkDisconnectedError(
        "Không thể kết nối đến API Server",
        err,
      );
    }

    const body = (await res.json()) as ApiSuccessResponse<T> | ApiErrorResponse;

    if (!res.ok || !body.success) {
      const errorBody = body as ApiErrorResponse;
      const code = errorBody.error?.code || "ERR_API";
      const message = errorBody.error?.message || res.statusText;
      if (res.status === 404) {
        throw new RunNotFoundError(path);
      }
      throw new HarnessSDKError(code, message, errorBody.error?.details);
    }

    return body.data;
  }

  public async createRun(params: CreateRunDto): Promise<Run> {
    return this.request<Run>("/api/v1/runs", {
      method: "POST",
      body: JSON.stringify(params),
    });
  }

  public async getRun(runId: string): Promise<Run> {
    return this.request<Run>(`/api/v1/runs/${runId}`);
  }

  /**
   * I3 + NC3 Fix: Trả PaginatedResult với đúng shape từ API.
   * Server dùng _paginated flag → interceptor đưa items vào data, pagination vào meta.
   */
  public async listRuns(query?: {
    page?: number;
    pageSize?: number;
    status?: string;
  }): Promise<PaginatedResult<Run>> {
    const params = new URLSearchParams();
    if (query?.page) params.set("page", String(query.page));
    if (query?.pageSize) params.set("pageSize", String(query.pageSize));
    if (query?.status) params.set("status", query.status);
    const qs = params.toString();

    const url = `${this.baseUrl}/api/v1/runs${qs ? `?${qs}` : ""}`;
    let res: Response;
    try {
      res = await fetch(url, { headers: this.defaultHeaders });
    } catch (err) {
      throw new NetworkDisconnectedError(
        "Không thể kết nối đến API Server",
        err,
      );
    }
    const body = (await res.json()) as
      ApiSuccessResponse<Run[]> | ApiErrorResponse;
    if (!res.ok || !body.success) {
      const errorBody = body as ApiErrorResponse;
      throw new HarnessSDKError(
        errorBody.error?.code || "ERR_API",
        errorBody.error?.message || res.statusText,
      );
    }
    const successBody = body;
    return {
      items: successBody.data,
      // pagination nằm trong meta (do interceptor đưa vào sau khi thấy _paginated flag)
      pagination: successBody.meta.pagination as PaginationMeta,
    };
  }

  public async getToolCalls(
    runId: string,
    query?: { fromStep?: number; limit?: number },
  ): Promise<ToolCall[]> {
    const params = new URLSearchParams();
    if (query?.fromStep !== undefined)
      params.set("fromStep", String(query.fromStep));
    if (query?.limit !== undefined) params.set("limit", String(query.limit));
    const qs = params.toString();
    return this.request<ToolCall[]>(
      `/api/v1/runs/${runId}/tool-calls${qs ? `?${qs}` : ""}`,
    );
  }

  public async getModelEvents(
    runId: string,
    query?: { fromStep?: number; limit?: number },
  ): Promise<ModelEvent[]> {
    const params = new URLSearchParams();
    if (query?.fromStep !== undefined)
      params.set("fromStep", String(query.fromStep));
    if (query?.limit !== undefined) params.set("limit", String(query.limit));
    const qs = params.toString();
    return this.request<ModelEvent[]>(
      `/api/v1/runs/${runId}/model-events${qs ? `?${qs}` : ""}`,
    );
  }

  public async cancelRun(runId: string): Promise<Run> {
    // W5 Fix: x-request-id bắt buộc theo spec để đảm bảo idempotency trace
    const requestId = `req_cancel_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    return this.request<Run>(`/api/v1/runs/${runId}/cancel`, {
      method: "POST",
      headers: {
        "x-request-id": requestId,
      },
    });
  }

  public subscribeRunStream(
    runId: string,
    listener: RunStreamListener,
    options?: StreamConnectionOptions,
  ): () => void {
    const abortController = new AbortController();
    const url = new URL(`${this.baseUrl}/api/v1/runs/${runId}/stream`);
    if (options?.fromStep !== undefined) {
      url.searchParams.set("fromStep", String(options.fromStep));
    }

    void fetchEventSource(url.toString(), {
      headers: {
        ...this.defaultHeaders,
        ...(options?.fromStep !== undefined && {
          "Last-Event-ID": String(options.fromStep),
        }),
      },
      signal: abortController.signal,
      onopen: async (response) => {
        if (!response.ok) {
          throw new NetworkDisconnectedError(
            `SSE connection failed: HTTP ${response.status}`,
          );
        }
        // C4 Fix: onopen gọi sau khi HTTP 200 xác nhận — đảm bảo
        // không có race condition với onError
        listener.onopen?.();
      },
      onmessage: (event) => {
        if (event.event === "heartbeat") return;
        try {
          const data = JSON.parse(event.data);
          switch (event.event) {
            case "step:thought":
              listener.onThought?.(data as ThoughtEvent);
              break;
            case "step:tool_call":
              listener.onToolCall?.(data as ToolCallEvent);
              break;
            case "run:status_changed":
              listener.onStatusChanged?.(data as StatusChangedEvent);
              break;
            case "run:verdict":
              listener.onVerdict?.(data as VerdictEvent);
              break;
            case "run:completed":
              listener.onCompleted?.(data as CompletedEvent);
              abortController.abort();
              break;
          }
        } catch (e) {
          listener.onError?.(e);
        }
      },
      onerror: (err) => {
        listener.onError?.(err);
      },
      openWhenHidden: true,
    });

    return () => {
      abortController.abort();
    };
  }
}
